'''
Core logic for the Wordle game, including word selection, guess validation, and feedback generation.
'''
import random
class WordleGame:
    def __init__(self, word_list):
        self.word_list = word_list
        self.target_word = random.choice(self.word_list)
    def validate_guess(self, guess):
        return len(guess) == 5 and guess in self.word_list
    def get_feedback(self, guess):
        feedback = []
        for i, letter in enumerate(guess):
            if letter == self.target_word[i]:
                feedback.append(f"\033[92m{letter.upper()}\033[0m")  # Green
            elif letter in self.target_word:
                feedback.append(f"\033[93m{letter.upper()}\033[0m")  # Yellow
            else:
                feedback.append(f"\033[90m{letter.upper()}\033[0m")  # Grey
        return ' '.join(feedback)
    def is_correct_guess(self, guess):
        return guess == self.target_word
